mapper.sql:
SELECT gt.subject_id AS user_id FROM grant_table gt WHERE gt.subject_type = 'USER' AND gt.role_code IN
#{roleCode}
UNION SELECT ud.user_id FROM grant_table gt INNER JOIN user_dept ud ON gt.subject_type = 'DEPT' INNER JOIN dept_closure dc ON ud.dept_id = dc.descendant_id AND dc.ancestor_id = gt.subject_id WHERE gt.role_code IN
#{roleCode}
AND ud.status IN (1, 2) UNION SELECT up.user_id FROM grant_table gt INNER JOIN user_post up ON gt.subject_type = 'POST' AND up.post_id = gt.subject_id WHERE gt.role_code IN
#{roleCode}
AND up.status IN (1, 2)

SELECT ud.user_id FROM grant_table gt INNER JOIN user_dept ud ON gt.subject_type = 'DEPT' INNER JOIN dept_closure dc ON ud.dept_id = dc.descendant_id AND dc.ancestor_id = gt.subject_id WHERE gt.subject_type = 'DEPT' AND gt.subject_id IN
#{subjectId}
AND ud.status IN (1, 2)

SELECT up.user_id FROM grant_table gt INNER JOIN user_post up ON gt.subject_type = 'POST' AND up.post_id = gt.subject_id WHERE gt.subject_type = 'POST' AND gt.subject_id IN
#{subjectId}
AND up.status IN (1, 2)

SELECT DISTINCT ud.user_id FROM user_dept ud INNER JOIN dept_closure dc ON ud.dept_id = dc.descendant_id WHERE dc.ancestor_id IN
#{deptId}
AND ud.status IN (1, 2)

SELECT DISTINCT up.user_id FROM user_post up WHERE up.post_id IN
#{postId}
AND up.status IN (1, 2)

SELECT DISTINCT rp.role_code FROM sys_role_permission rp INNER JOIN sys_permission p ON p.permission_code = rp.permission_code WHERE rp.permission_code IN
#{permissionCode}
AND p.status = 1 AND p.is_deleted = 0

SELECT DISTINCT rp.role_code FROM role_policy rp WHERE rp.policy_code IN
#{policyCode}
AND rp.is_deleted = 0

SELECT DISTINCT b.user_id FROM user_access_policy_binding b WHERE b.policy_code IN
#{policyCode}
AND b.is_deleted = 0
